package com.anitec.backend;

import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

@Testcontainers
class EmailOutboxMigrationTests {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 DriverManagerDataSource database(){String name="email_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword())).execute("CREATE DATABASE "+name);return new DriverManagerDataSource("jdbc:postgresql://"+postgres.getHost()+":"+postgres.getMappedPort(5432)+"/"+name,postgres.getUsername(),postgres.getPassword());}
 Flyway flyway(DriverManagerDataSource db,String version){return Flyway.configure().dataSource(db).target(version).placeholders(Map.of("admin_email","retired@bootstrap.invalid","admin_password_hash","DISABLED-HISTORICAL-BOOTSTRAP","demo_seed","false")).load();}
 @Test void freshInstallationAndRepeatedFlyway(){var db=database();assertThat(flyway(db,"17").migrate().migrationsExecuted).isEqualTo(17);var jdbc=new JdbcTemplate(db);assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_accounts",Integer.class)).isZero();assertThat(flyway(db,"17").migrate().migrationsExecuted).isZero();}
 @Test void upgradeV16PreservesExistingAccountCodeCountersAndRecovery(){var db=database();flyway(db,"16").migrate();var j=new JdbcTemplate(db);UUID account=j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verification_code,verification_expires_at,verification_sent_at,verification_attempts,verification_resends,verification_window_started_at) VALUES ('preserved@example.invalid','synthetic-hash','Test','Migration','GANADERO','PENDIENTE','000007',now()+interval '10 minutes',now(),3,4,now()) RETURNING id",UUID.class);UUID emission=UUID.randomUUID();j.update("INSERT INTO identity_password_recovery(account_id,purpose,window_started_at,emission_count,last_issued_at,emission_id,code_verifier,expires_at,failed_attempts) VALUES (?,'PASSWORD_RECOVERY',now(),2,now(),?,decode(repeat('ab',32),'hex'),now()+interval '10 minutes',2)",account,emission);var before=j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",account);var recovery=j.queryForMap("SELECT * FROM identity_password_recovery WHERE account_id=?",account);assertThat(flyway(db,"17").migrate().migrationsExecuted).isEqualTo(1);var after=j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",account);assertThat(after.remove("verification_emission_id")).isInstanceOf(UUID.class);assertThat(after).isEqualTo(before);var r=j.queryForMap("SELECT * FROM identity_password_recovery WHERE account_id=?",account);assertThat((byte[])r.remove("code_verifier")).isEqualTo((byte[])recovery.remove("code_verifier"));assertThat(r).isEqualTo(recovery);assertThat(j.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}
 @Test void opaqueVerificationIdentityChangesOnlyOnCodeReplacement(){var db=database();flyway(db,"17").migrate();var j=new JdbcTemplate(db);UUID account=j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verification_code) VALUES ('opaque@example.invalid','synthetic-hash','Test','Migration','GANADERO','PENDIENTE','000007') RETURNING id",UUID.class);UUID before=j.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,account);j.update("UPDATE identity_accounts SET verification_attempts=1 WHERE id=?",account);assertThat(j.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,account)).isEqualTo(before);j.update("UPDATE identity_accounts SET verification_code='000008' WHERE id=?",account);assertThat(j.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,account)).isNotEqualTo(before);}
}
